"""Embedded frontend HTML — bundled directly into the Python function
since Vercel does not include sibling project files (like the root
index.html) inside the deployed function package."""

INDEX_HTML = '<!DOCTYPE html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="UTF-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />\n<title>ASTRA — AI Space Sentinel</title>\n<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css" />\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet">\n<style>\n  :root {\n    --bg: #0a0e14;\n    --panel: #10161f;\n    --panel-2: #151d29;\n    --line: #212b38;\n    --text: #e7ebf0;\n    --muted: #8a97a8;\n    --signal: #4fd1c5;\n    --signal-dim: #245852;\n    --warn: #f0a94e;\n    --alert: #e5555a;\n  }\n  * { box-sizing: border-box; }\n  html, body {\n    height: 100%;\n    margin: 0;\n    background: var(--bg);\n    color: var(--text);\n    font-family: \'IBM Plex Sans\', -apple-system, sans-serif;\n    padding-top: env(safe-area-inset-top, 0px);\n    padding-bottom: env(safe-area-inset-bottom, 0px);\n  }\n  .mono { font-family: \'IBM Plex Mono\', monospace; }\n\n  header {\n    padding: 22px 28px 18px;\n    border-bottom: 1px solid var(--line);\n    display: flex;\n    align-items: baseline;\n    gap: 14px;\n    flex-wrap: wrap;\n  }\n  header h1 {\n    margin: 0;\n    font-size: 22px;\n    font-weight: 700;\n    letter-spacing: 0.2px;\n  }\n  header h1 span { color: var(--signal); }\n  header p {\n    margin: 0;\n    color: var(--muted);\n    font-size: 14px;\n  }\n\n  .layout {\n    display: grid;\n    grid-template-columns: 340px 1fr;\n    min-height: calc(100% - 78px);\n  }\n  @media (max-width: 860px) {\n    .layout { grid-template-columns: 1fr; }\n  }\n\n  .controls {\n    border-left: 1px solid var(--line);\n    padding: 22px;\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n    overflow-y: auto;\n  }\n  .field label {\n    display: block;\n    font-size: 12.5px;\n    color: var(--muted);\n    margin-bottom: 6px;\n  }\n  .field select, .field input {\n    width: 100%;\n    background: var(--panel-2);\n    border: 1px solid var(--line);\n    color: var(--text);\n    padding: 9px 10px;\n    border-radius: 6px;\n    font-size: 14px;\n    font-family: inherit;\n  }\n  .field input:focus, .field select:focus {\n    outline: none;\n    border-color: var(--signal);\n  }\n  .row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n\n  .period {\n    background: var(--panel);\n    border: 1px solid var(--line);\n    border-radius: 8px;\n    padding: 12px;\n  }\n  .period-title { font-size: 12.5px; color: var(--signal); margin-bottom: 10px; font-weight: 600; }\n\n  button#analyzeBtn {\n    margin-top: 4px;\n    background: var(--signal);\n    color: #06201d;\n    border: none;\n    padding: 12px 14px;\n    border-radius: 6px;\n    font-weight: 600;\n    font-size: 14.5px;\n    cursor: pointer;\n  }\n  button#analyzeBtn:hover { background: #66e0d4; }\n  button#analyzeBtn:disabled { background: var(--signal-dim); color: var(--muted); cursor: progress; }\n\n  main { position: relative; display: flex; flex-direction: column; }\n  #map { flex: 1; min-height: 320px; }\n\n  #results {\n    border-top: 1px solid var(--line);\n    background: var(--panel);\n    padding: 20px 24px;\n    display: none;\n  }\n  #results.show { display: block; }\n\n  .result-head { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; flex-wrap: wrap; }\n  .severity-tag {\n    font-size: 12px;\n    padding: 4px 10px;\n    border-radius: 4px;\n    font-weight: 600;\n  }\n  .sev-low { background: rgba(79,209,197,0.15); color: var(--signal); }\n  .sev-medium { background: rgba(240,169,78,0.15); color: var(--warn); }\n  .sev-high { background: rgba(229,85,90,0.15); color: var(--alert); }\n\n  .result-head .pct { font-size: 26px; font-weight: 700; }\n  .result-head .idx-label { color: var(--muted); font-size: 13px; }\n\n  .explanation {\n    color: var(--text);\n    font-size: 14.5px;\n    line-height: 1.6;\n    max-width: 640px;\n    margin-bottom: 18px;\n  }\n\n  .thumbs { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; max-width: 720px; }\n  .thumb { border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }\n  .thumb img { width: 100%; display: block; background: #05080c; }\n  .thumb-label {\n    font-size: 11.5px;\n    color: var(--muted);\n    padding: 6px 10px;\n    border-top: 1px solid var(--line);\n  }\n\n  #status { color: var(--muted); font-size: 13px; margin-top: 10px; min-height: 18px; }\n  #status.err { color: var(--alert); }\n</style>\n</head>\n<body>\n\n<header>\n  <h1>ASTRA <span>· AI Space Sentinel</span></h1>\n  <p>يحوّل صور الأقمار الصناعية إلى إنذار مبكر قابل للفهم</p>\n</header>\n\n<div class="layout">\n  <div class="controls">\n    <div class="field">\n      <label>المنطقة</label>\n      <select id="regionSelect">\n        <option value="44.2,33.2,44.5,33.4">بغداد وضواحيها</option>\n        <option value="47.6,30.4,47.9,30.6">البصرة والأهوار</option>\n        <option value="43.6,36.2,43.9,36.4">دهوك</option>\n        <option value="custom">تحديد يدوي (ارسم على الخريطة)</option>\n      </select>\n    </div>\n\n    <div class="field">\n      <label>المؤشر المستخدم</label>\n      <select id="indexSelect">\n        <option value="NDVI">NDVI — الغطاء النباتي</option>\n        <option value="NDWI">NDWI — المسطحات المائية</option>\n      </select>\n    </div>\n\n    <div class="period">\n      <div class="period-title">الفترة المرجعية (Before)</div>\n      <div class="row2">\n        <div class="field"><label>من</label><input type="date" id="beforeStart" value="2023-01-01"></div>\n        <div class="field"><label>إلى</label><input type="date" id="beforeEnd" value="2023-03-01"></div>\n      </div>\n    </div>\n\n    <div class="period">\n      <div class="period-title">فترة المقارنة (After)</div>\n      <div class="row2">\n        <div class="field"><label>من</label><input type="date" id="afterStart" value="2024-01-01"></div>\n        <div class="field"><label>إلى</label><input type="date" id="afterEnd" value="2024-03-01"></div>\n      </div>\n    </div>\n\n    <button id="analyzeBtn">تشغيل التحليل</button>\n    <div id="status" class="mono"></div>\n  </div>\n\n  <main>\n    <div id="map"></div>\n    <div id="results">\n      <div class="result-head">\n        <span id="sevTag" class="severity-tag sev-low">—</span>\n        <span class="pct mono" id="pctValue">0%</span>\n        <span class="idx-label" id="idxLabel"></span>\n      </div>\n      <p class="explanation" id="explanationText"></p>\n      <div class="thumbs">\n        <div class="thumb">\n          <img id="beforeImg" alt="before" />\n          <div class="thumb-label mono">BEFORE</div>\n        </div>\n        <div class="thumb">\n          <img id="afterImg" alt="after" />\n          <div class="thumb-label mono">AFTER</div>\n        </div>\n      </div>\n    </div>\n  </main>\n</div>\n\n<script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js"></script>\n<script>\n  const map = L.map(\'map\', { zoomControl: true }).setView([33.3, 44.35], 7);\n  L.tileLayer(\'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png\', {\n    attribution: \'&copy; OpenStreetMap contributors\',\n    maxZoom: 18\n  }).addTo(map);\n\n  let rectLayer = null;\n  function drawRegion(minLon, minLat, maxLon, maxLat) {\n    if (rectLayer) map.removeLayer(rectLayer);\n    const bounds = [[minLat, minLon], [maxLat, maxLon]];\n    rectLayer = L.rectangle(bounds, { color: \'#4fd1c5\', weight: 2, fillOpacity: 0.08 }).addTo(map);\n    map.fitBounds(bounds, { padding: [40, 40] });\n  }\n\n  const regionSelect = document.getElementById(\'regionSelect\');\n  function currentRegion() {\n    const val = regionSelect.value;\n    if (val === \'custom\') return null; // drawing on map not implemented in this prototype\n    return val.split(\',\').map(Number);\n  }\n  regionSelect.addEventListener(\'change\', () => {\n    const r = currentRegion();\n    if (r) drawRegion(...r);\n  });\n  drawRegion(...currentRegion());\n\n  const statusEl = document.getElementById(\'status\');\n  const analyzeBtn = document.getElementById(\'analyzeBtn\');\n  const results = document.getElementById(\'results\');\n\n  analyzeBtn.addEventListener(\'click\', async () => {\n    const region = currentRegion();\n    if (!region) {\n      statusEl.textContent = \'التحديد اليدوي غير مفعّل بعد بهذا النموذج الأولي — اختر منطقة من القائمة.\';\n      statusEl.classList.add(\'err\');\n      return;\n    }\n    const [min_lon, min_lat, max_lon, max_lat] = region;\n    const body = {\n      min_lon, min_lat, max_lon, max_lat,\n      before_start: document.getElementById(\'beforeStart\').value,\n      before_end: document.getElementById(\'beforeEnd\').value,\n      after_start: document.getElementById(\'afterStart\').value,\n      after_end: document.getElementById(\'afterEnd\').value,\n      index: document.getElementById(\'indexSelect\').value\n    };\n\n    analyzeBtn.disabled = true;\n    statusEl.classList.remove(\'err\');\n    statusEl.textContent = \'جارٍ سحب صور الأقمار الصناعية وتحليلها... قد تستغرق العملية بضع ثوانٍ.\';\n    results.classList.remove(\'show\');\n\n    try {\n      const res = await fetch(\'/api/analyze\', {\n        method: \'POST\',\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify(body)\n      });\n      if (!res.ok) {\n        const errBody = await res.json().catch(() => ({}));\n        throw new Error(errBody.detail || `HTTP ${res.status}`);\n      }\n      const data = await res.json();\n      renderResult(data);\n      statusEl.textContent = \'اكتمل التحليل.\';\n    } catch (err) {\n      statusEl.textContent = \'صار خطأ: \' + err.message;\n      statusEl.classList.add(\'err\');\n    } finally {\n      analyzeBtn.disabled = false;\n    }\n  });\n\n  function renderResult(data) {\n    const tag = document.getElementById(\'sevTag\');\n    tag.className = \'severity-tag sev-\' + data.severity;\n    tag.textContent = data.severity === \'low\' ? \'طبيعي\' : data.severity === \'medium\' ? \'تنبيه متوسط\' : \'تنبيه مرتفع\';\n\n    document.getElementById(\'pctValue\').textContent =\n      (data.percent_change > 0 ? \'+\' : \'\') + data.percent_change + \'%\';\n    document.getElementById(\'idxLabel\').textContent = data.index + \' · \' + data.direction;\n    document.getElementById(\'explanationText\').textContent = data.explanation;\n    document.getElementById(\'beforeImg\').src = data.before_thumbnail;\n    document.getElementById(\'afterImg\').src = data.after_thumbnail;\n\n    results.classList.add(\'show\');\n  }\n</script>\n</body>\n</html>\n'
